package com.runechronicle;
import java.awt.*;import java.util.*;import javax.swing.*;import javax.swing.border.*;import javax.swing.event.*;import net.runelite.client.game.ItemManager;import net.runelite.client.util.AsyncBufferedImage;
final class BreakdownDialog{
 private static final Color BG=new Color(8,10,13),CARD=new Color(17,20,25),LINE=new Color(47,53,62),GOLD=new Color(242,187,59),WHITE=new Color(242,245,248),MUTED=new Color(151,160,173),GREEN=new Color(83,207,137);
 static void show(Component owner,String kind,RuneChroniclePlugin.Summary s,ItemManager items,RuneChroniclePlugin plugin){JDialog d=new JDialog(SwingUtilities.getWindowAncestor(owner),title(kind),Dialog.ModalityType.MODELESS);d.setDefaultCloseOperation(WindowConstants.DISPOSE_ON_CLOSE);JPanel root=new JPanel();root.setLayout(new BoxLayout(root,BoxLayout.Y_AXIS));root.setBackground(BG);root.setBorder(new EmptyBorder(22,24,24,24));root.add(lab(title(kind),24,WHITE,Font.BOLD));root.add(lab(sub(kind,s),10,MUTED,Font.PLAIN));root.add(Box.createVerticalStrut(16));if("LOOT".equals(kind))loot(root,s,items,plugin,d);else if("XP".equals(kind))map(root,s.skillXp,"XP");else if("BOSSES".equals(kind))map(root,s.bossCounts,"defeated");else map(root,s.killCounts,"defeated");JScrollPane sc=new JScrollPane(root);sc.setBorder(null);sc.getViewport().setBackground(BG);sc.getVerticalScrollBar().setUnitIncrement(18);d.setContentPane(sc);d.setSize(670,700);d.setMinimumSize(new Dimension(540,460));d.setLocationRelativeTo(owner);d.getRootPane().registerKeyboardAction(e->d.dispose(),KeyStroke.getKeyStroke("ESCAPE"),JComponent.WHEN_IN_FOCUSED_WINDOW);d.setVisible(true);}
 private static void loot(JPanel root,RuneChroniclePlugin.Summary s,ItemManager items,RuneChroniclePlugin plugin,JDialog dialog){JPanel content=new JPanel();content.setLayout(new BoxLayout(content,BoxLayout.Y_AXIS));content.setOpaque(false);content.setAlignmentX(Component.LEFT_ALIGNMENT);Runnable[] render=new Runnable[1];render[0]=()->{content.removeAll();long hidden=0;Map<String,java.util.List<ChronicleStore.Event>> by=new LinkedHashMap<>();for(ChronicleStore.Event e:s.events)if("LOOT".equals(e.type)){if(plugin.isLootTemporarilyHidden(e.itemId)||plugin.isLootHidden(e.itemId)){hidden+=e.value;continue;}by.computeIfAbsent(e.source==null||e.source.isEmpty()?"Other loot":e.source,k->new ArrayList<>()).add(e);}JPanel totals=new JPanel(new GridLayout(1,3,6,0));totals.setOpaque(false);totals.add(metric("VISIBLE",RuneChroniclePlugin.gp(Math.max(0,s.lootValue-hidden))+" gp"));JButton hiddenButton=new JButton("<html><center><span style='font-size:8px'>HIDDEN</span><br><b>"+RuneChroniclePlugin.gp(hidden)+" gp →</b></center></html>");styleMetric(hiddenButton);hiddenButton.setToolTipText("Click to see which hidden items make up this value");hiddenButton.addActionListener(x->manageHidden(dialog,items,plugin,s,render[0]));totals.add(hiddenButton);totals.add(metric("TOTAL",RuneChroniclePlugin.gp(s.lootValue)+" gp"));totals.setMaximumSize(new Dimension(Integer.MAX_VALUE,54));content.add(totals);JButton manage=new JButton("MANAGE HIDDEN LOOT →");styleButton(manage);manage.addActionListener(x->manageHidden(dialog,items,plugin,s,render[0]));content.add(Box.createVerticalStrut(7));content.add(manage);if(by.isEmpty())content.add(empty("No visible recorded loot in this period."));for(Map.Entry<String,java.util.List<ChronicleStore.Event>> g:by.entrySet()){long total=0;for(ChronicleStore.Event e:g.getValue())total+=e.value;content.add(section(g.getKey()+"  ·  "+RuneChroniclePlugin.gp(total)+" gp"));for(ChronicleStore.Event e:g.getValue())content.add(lootRow(e,items,plugin,render[0]));}content.revalidate();content.repaint();};root.add(content);render[0].run();}
 private static JPanel metric(String title,String value){JPanel p=card(new BorderLayout());JPanel m=new JPanel();m.setOpaque(false);m.setLayout(new BoxLayout(m,BoxLayout.Y_AXIS));JLabel a=lab(title,8,MUTED,Font.BOLD);a.setAlignmentX(Component.CENTER_ALIGNMENT);JLabel b=lab(value,11,GOLD,Font.BOLD);b.setAlignmentX(Component.CENTER_ALIGNMENT);m.add(a);m.add(b);p.add(m);p.setMaximumSize(new Dimension(Integer.MAX_VALUE,54));return p;}
 private static JPanel lootRow(ChronicleStore.Event e,ItemManager items,RuneChroniclePlugin plugin,Runnable rerender){JPanel p=card(new BorderLayout(12,0));JLabel art=new JLabel();art.setPreferredSize(new Dimension(44,44));try{AsyncBufferedImage im=items.getImage(e.itemId,Math.max(1,e.quantity),e.quantity>1);if(im!=null)im.addTo(art);}catch(Exception ignored){}p.add(art,BorderLayout.WEST);JPanel m=new JPanel();m.setOpaque(false);m.setLayout(new BoxLayout(m,BoxLayout.Y_AXIS));m.add(lab(e.title+" ×"+Math.max(1,e.quantity),12,WHITE,Font.BOLD));long unit=e.quantity>0?e.value/e.quantity:e.value;m.add(lab(RuneChroniclePlugin.gp(unit)+" gp ea  ·  "+RuneChroniclePlugin.gp(e.value)+" gp total",9,GOLD,Font.PLAIN));m.add(lab("High Alch: "+RuneChroniclePlugin.gp(e.haValue)+" gp total",9,MUTED,Font.PLAIN));p.add(m,BorderLayout.CENTER);JPanel actions=new JPanel();actions.setOpaque(false);actions.setLayout(new BoxLayout(actions,BoxLayout.Y_AXIS));JButton hide=new JButton("HIDE");styleSmall(hide);hide.setToolTipText("Hide this item from the current loot view");hide.addActionListener(x->{plugin.hideLootTemporarily(e.itemId);rerender.run();});JButton always=new JButton("ALWAYS HIDE");styleSmall(always);always.setToolTipText("Hide this item from future loot breakdowns until you unhide it");always.addActionListener(x->{plugin.hideLoot(e.itemId);rerender.run();});actions.add(hide);actions.add(Box.createVerticalStrut(3));actions.add(always);p.add(actions,BorderLayout.EAST);return p;}
 private static void manageHidden(Component owner,ItemManager items,RuneChroniclePlugin plugin,RuneChroniclePlugin.Summary s,Runnable parentRender){Window parent=owner instanceof Window?(Window)owner:SwingUtilities.getWindowAncestor(owner);JDialog d=new JDialog(parent,"Hidden Loot",Dialog.ModalityType.MODELESS);d.setDefaultCloseOperation(WindowConstants.DISPOSE_ON_CLOSE);JPanel root=new JPanel();root.setLayout(new BoxLayout(root,BoxLayout.Y_AXIS));root.setBackground(BG);root.setBorder(new EmptyBorder(18,18,18,18));root.add(lab("HIDDEN LOOT",20,WHITE,Font.BOLD));root.add(lab("Temporary and always-hidden loot. Type part of an item name to bring matching hidden items to the top.",9,MUTED,Font.PLAIN));JTextField q=new JTextField();q.setToolTipText("Try: bon, rune, herb...");q.setMaximumSize(new Dimension(Integer.MAX_VALUE,32));q.setAlignmentX(Component.LEFT_ALIGNMENT);root.add(Box.createVerticalStrut(10));root.add(q);JPanel rows=new JPanel();rows.setLayout(new BoxLayout(rows,BoxLayout.Y_AXIS));rows.setOpaque(false);root.add(Box.createVerticalStrut(8));root.add(rows);JScrollPane sp=new JScrollPane(root);sp.setBorder(null);sp.getViewport().setBackground(BG);sp.getVerticalScrollBar().setUnitIncrement(16);d.setContentPane(sp);d.setSize(570,570);d.setLocationRelativeTo(parent);Runnable[] render=new Runnable[1];render[0]=()->{rows.removeAll();try{String needle=q.getText().trim().toLowerCase(Locale.ROOT);Set<Integer> permanent=new LinkedHashSet<>(plugin.hiddenLootIds()),temporary=new LinkedHashSet<>(plugin.temporaryHiddenLootIds()),ids=new LinkedHashSet<>();ids.addAll(temporary);ids.addAll(permanent);Map<Integer,long[]> totals=new LinkedHashMap<>();Map<Integer,String> names=new LinkedHashMap<>();java.util.List<JPanel> matchedRows=new ArrayList<>(),otherRows=new ArrayList<>();for(ChronicleStore.Event e:s.events)if(("LOOT".equals(e.type)||"PROFIT_LOOT".equals(e.type))&&ids.contains(e.itemId)){long[] a=totals.computeIfAbsent(e.itemId,k->new long[3]);a[0]+=Math.max(1,e.quantity);a[1]+=e.value;a[2]+=e.haValue;if(e.title!=null&&!e.title.trim().isEmpty())names.putIfAbsent(e.itemId,e.title.trim());}int shown=0;for(int id:ids){try{String name=names.get(id);if(name==null||name.isEmpty()){name="Item "+id;try{if(items.getItemComposition(id)!=null&&items.getItemComposition(id).getName()!=null)name=items.getItemComposition(id).getName();}catch(Exception ignored){}}boolean searchMatch=needle.isEmpty()||name.toLowerCase(Locale.ROOT).contains(needle);shown++;long[] a=totals.getOrDefault(id,new long[3]);JPanel row=card(new BorderLayout(10,0));JLabel art=new JLabel();art.setPreferredSize(new Dimension(38,38));try{AsyncBufferedImage im=items.getImage(id,(int)Math.min(Integer.MAX_VALUE,Math.max(1,a[0])),a[0]>1);if(im!=null)im.addTo(art);}catch(Exception ignored){}row.add(art,BorderLayout.WEST);JPanel info=new JPanel();info.setOpaque(false);info.setLayout(new BoxLayout(info,BoxLayout.Y_AXIS));info.add(lab((!needle.isEmpty()&&searchMatch?"▶ ":"")+name+(a[0]>0?" ×"+a[0]:""),11,!needle.isEmpty()&&searchMatch?GOLD:WHITE,Font.BOLD));String state=permanent.contains(id)?"ALWAYS HIDDEN":"HIDDEN THIS VIEW";info.add(lab(state+"  ·  "+RuneChroniclePlugin.gp(a[1])+" gp in this breakdown",8,permanent.contains(id)?GOLD:MUTED,Font.BOLD));row.add(info,BorderLayout.CENTER);JButton unhide=new JButton("UNHIDE");styleSmall(unhide);final int itemId=id;unhide.addActionListener(x->{plugin.unhideLoot(itemId);try{parentRender.run();}catch(Exception ignored){}render[0].run();});row.add(unhide,BorderLayout.EAST);if(!needle.isEmpty()&&searchMatch)matchedRows.add(row);else otherRows.add(row);}catch(Exception itemError){rows.add(empty("Hidden item "+id+" could not be rendered. You can still use UNHIDE ALL below."));}}for(JPanel row:matchedRows)rows.add(row);for(JPanel row:otherRows)rows.add(row);if(ids.isEmpty())rows.add(empty("Nothing is hidden."));JButton all=new JButton("UNHIDE ALL");styleButton(all);all.addActionListener(x->{plugin.unhideAllLoot();try{parentRender.run();}catch(Exception ignored){}render[0].run();});rows.add(Box.createVerticalStrut(8));rows.add(all);}catch(Exception ex){rows.add(empty("Hidden loot could not be rendered. Use UNHIDE ALL to restore hidden items."));JButton all=new JButton("UNHIDE ALL");styleButton(all);all.addActionListener(x->{plugin.unhideAllLoot();try{parentRender.run();}catch(Exception ignored){}render[0].run();});rows.add(Box.createVerticalStrut(8));rows.add(all);}rows.revalidate();rows.repaint();};javax.swing.Timer searchTimer=new javax.swing.Timer(90,e->render[0].run());searchTimer.setRepeats(false);q.getDocument().addDocumentListener(new DocumentListener(){private void changed(){searchTimer.restart();}public void insertUpdate(DocumentEvent e){changed();}public void removeUpdate(DocumentEvent e){changed();}public void changedUpdate(DocumentEvent e){changed();}});d.addWindowListener(new java.awt.event.WindowAdapter(){@Override public void windowClosed(java.awt.event.WindowEvent e){searchTimer.stop();}});d.setVisible(true);d.toFront();d.requestFocus();SwingUtilities.invokeLater(render[0]);}
 private static void map(JPanel root,Map<String,Long> m,String suffix){if(m.isEmpty()){root.add(empty("Nothing recorded in this period."));return;}m.entrySet().stream().sorted((a,b)->Long.compare(b.getValue(),a.getValue())).forEach(e->{JPanel p=card(new BorderLayout());p.add(lab(e.getKey(),12,WHITE,Font.BOLD),BorderLayout.WEST);p.add(lab("XP".equals(suffix)?"+"+String.format("%,d",e.getValue())+" XP":"×"+e.getValue(),11,"XP".equals(suffix)?GREEN:GOLD,Font.BOLD),BorderLayout.EAST);root.add(p);});}
 private static String title(String k){return "LOOT".equals(k)?"Loot Breakdown":"XP".equals(k)?"XP Breakdown":"BOSSES".equals(k)?"Boss Breakdown":"Kill Breakdown";}private static String sub(String k,RuneChroniclePlugin.Summary s){if("LOOT".equals(k))return RuneChroniclePlugin.gp(s.lootValue)+" gp total · "+s.lootItems+" items claimed";if("XP".equals(k))return String.format("%,d",s.xp)+" XP earned";if("BOSSES".equals(k))return s.bossKills+" bosses defeated";return s.kills+" monsters defeated";}
 private static JLabel section(String x){JLabel l=lab(x,11,GOLD,Font.BOLD);l.setBorder(new EmptyBorder(16,2,7,2));return l;}private static JPanel card(LayoutManager l){JPanel p=new JPanel(l);p.setBackground(CARD);p.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createEmptyBorder(2,0,2,0),BorderFactory.createCompoundBorder(BorderFactory.createLineBorder(LINE),new EmptyBorder(11,12,11,12))));p.setMaximumSize(new Dimension(Integer.MAX_VALUE,78));return p;}private static JPanel empty(String x){JPanel p=card(new BorderLayout());p.add(lab(x,10,MUTED,Font.PLAIN));return p;}private static JLabel lab(String s,int z,Color c,int st){JLabel l=new JLabel(s);l.setForeground(c);l.setFont(new Font("SansSerif",st,z));return l;}private static void styleButton(JButton b){b.setFocusable(false);b.setForeground(GOLD);b.setBackground(CARD);b.setBorder(new CompoundBorder(new LineBorder(LINE),new EmptyBorder(8,9,8,9)));b.setMaximumSize(new Dimension(Integer.MAX_VALUE,38));b.setAlignmentX(Component.LEFT_ALIGNMENT);}private static void styleSmall(JButton b){b.setFocusable(false);b.setForeground(MUTED);b.setBackground(CARD);b.setFont(new Font("SansSerif",Font.BOLD,8));b.setMargin(new Insets(3,6,3,6));b.setBorder(new LineBorder(LINE));}private static void styleMetric(JButton b){b.setFocusable(false);b.setForeground(GOLD);b.setBackground(CARD);b.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createLineBorder(LINE),new EmptyBorder(5,4,5,4)));}
}

package com.runechronicle;
import java.awt.*;import javax.swing.*;import javax.swing.border.*;
final class ChronicleSettingsDialog extends JDialog{
 ChronicleSettingsDialog(RuneChroniclePlugin p){setTitle("RuneChronicle · Settings");setModal(false);setSize(470,700);setLocationRelativeTo(null);JPanel root=new JPanel();root.setLayout(new BoxLayout(root,BoxLayout.Y_AXIS));root.setBackground(RuneChroniclePanel.BG);root.setBorder(new EmptyBorder(20,22,22,22));
  root.add(text("RUNECHRONICLE",20,RuneChroniclePanel.WHITE,Font.BOLD));root.add(text("Journal controls · RuneChronicle 0.8.1",10,RuneChroniclePanel.GOLD,Font.BOLD));root.add(gap(14));
  root.add(section("WHAT TO REMEMBER"));JCheckBox loot=check("Claimed loot & rewards",p.config().logLoot()),kills=check("Monster kills",p.config().logMonsterKills()),bosses=check("Bosses defeated",p.config().logBossKills()),activities=check("Raids, chests, clues & activities",p.config().logActivities()),milestones=check("Quests, Collection Log, pets, PBs & achievements",p.config().logGameMilestones()),deaths=check("Deaths",p.config().logDeaths());for(JCheckBox c:new JCheckBox[]{loot,kills,bosses,activities,milestones,deaths})root.add(c);
  root.add(section("RECAP"));JCheckBox gameRecap=check("In-game RECAP control",p.config().showGameRecapButton()),recap=check("Sidebar OPEN RECAP button",p.config().showRecapEntry());root.add(gameRecap);root.add(recap);
  root.add(section("LOOT VALUE FILTER"));JLabel explain=text("<html><body style='width:395px'><b>Important:</b> This filter decides which claimed drops appear in your normal Chronicle. The default is <b>1 gp</b>, so almost all valued loot records automatically. Raise it only if you intentionally want to exclude cheaper drops.<br><br><b>Profit Tracker still counts claimed loot during an active tracked run even when this normal Chronicle filter would hide it.</b></body></html>",9,RuneChroniclePanel.MUTED,Font.PLAIN);explain.setBorder(new EmptyBorder(0,0,5,0));root.add(explain);root.add(label("MINIMUM GE VALUE (1 GP = ALMOST EVERYTHING)"));JSpinner ge=new JSpinner(new SpinnerNumberModel(p.config().minimumGeValue(),0,2000000000,1000));root.add(ge);root.add(label("MINIMUM HIGH ALCH VALUE (0 = DISABLED)"));JSpinner ha=new JSpinner(new SpinnerNumberModel(p.config().minimumHaValue(),0,2000000000,1000));root.add(ha);JCheckBox stack=check("Use whole stack value",p.config().useStackValue());root.add(stack);root.add(label("QUALIFY WHEN"));JComboBox<RuneChronicleConfig.LootValueRule> rule=new JComboBox<>(RuneChronicleConfig.LootValueRule.values());rule.setSelectedItem(p.config().lootValueRule());root.add(rule);
  root.add(section("YOUR CHRONICLE DATA"));JPanel data=new JPanel(new GridLayout(1,3,6,0));data.setOpaque(false);JButton export=btn("EXPORT"),imp=btn("IMPORT"),reset=btn("RESET");export.addActionListener(e->p.exportChronicle(this));imp.addActionListener(e->p.importChronicle(this));reset.addActionListener(e->p.resetChronicle(this));data.add(export);data.add(imp);data.add(reset);root.add(data);JLabel local=text("History is stored on this device and does not automatically sync between computers. Use Export / Import to move a backup.",9,RuneChroniclePanel.MUTED,Font.PLAIN);local.setBorder(new EmptyBorder(7,0,5,0));root.add(local);
  JLabel artwork=text("<html><body style='width:395px'><b>External artwork:</b> NPC names are sent to the OSRS Wiki only to retrieve monster/boss images.<br>Your RSN, account identifier, Chronicle history, drops, credentials, and login/session data are not sent.</body></html>",9,RuneChroniclePanel.MUTED,Font.PLAIN);artwork.setBorder(new EmptyBorder(0,0,12,0));root.add(artwork);
  JPanel buttons=new JPanel(new GridLayout(1,2,8,0));buttons.setOpaque(false);JButton everything=btn("RECORD EVERYTHING"),save=btn("SAVE SETTINGS");everything.addActionListener(e->{ge.setValue(0);ha.setValue(0);loot.setSelected(true);kills.setSelected(true);bosses.setSelected(true);activities.setSelected(true);milestones.setSelected(true);deaths.setSelected(true);stack.setSelected(true);rule.setSelectedItem(RuneChronicleConfig.LootValueRule.GE_OR_HA);});save.addActionListener(e->{set(p,"logLoot",loot.isSelected());set(p,"logMonsterKills",kills.isSelected());set(p,"logBossKills",bosses.isSelected());set(p,"logActivities",activities.isSelected());set(p,"logGameMilestones",milestones.isSelected());set(p,"logDeaths",deaths.isSelected());set(p,"showRecapEntry",recap.isSelected());set(p,"showGameRecapButton",gameRecap.isSelected());set(p,"useStackValue",stack.isSelected());set(p,"minimumGeValue",ge.getValue());set(p,"minimumHaValue",ha.getValue());set(p,"lootValueRule",((RuneChronicleConfig.LootValueRule)rule.getSelectedItem()).name());p.refresh();dispose();});buttons.add(everything);buttons.add(save);root.add(buttons);
  JScrollPane sc=new JScrollPane(root);sc.setBorder(null);sc.getViewport().setBackground(RuneChroniclePanel.BG);sc.getVerticalScrollBar().setUnitIncrement(16);setContentPane(sc);}
 private static Component gap(int n){return Box.createVerticalStrut(n);}private static JButton btn(String s){JButton b=new JButton(s);b.setFocusable(false);b.setFont(new Font("SansSerif",Font.BOLD,9));return b;}private static JCheckBox check(String s,boolean v){JCheckBox c=new JCheckBox(s,v);c.setOpaque(false);c.setForeground(RuneChroniclePanel.WHITE);c.setFont(new Font("SansSerif",Font.PLAIN,11));return c;}private static JLabel section(String s){JLabel l=text(s,9,RuneChroniclePanel.GOLD,Font.BOLD);l.setBorder(new EmptyBorder(15,0,7,0));return l;}private static JLabel label(String s){JLabel l=text(s,8,RuneChroniclePanel.MUTED,Font.BOLD);l.setBorder(new EmptyBorder(8,0,4,0));return l;}private static JLabel text(String s,int z,Color c,int style){JLabel l=new JLabel(s);l.setForeground(c);l.setFont(new Font("SansSerif",style,z));return l;}private static void set(RuneChroniclePlugin p,String k,Object v){p.configManager().setConfiguration("runechronicle",k,v);}
}

package com.runechronicle;

import com.google.gson.*;
import java.io.*;
import java.time.Instant;
import net.runelite.client.util.Filepath;
import java.util.*;
import java.util.concurrent.*;
import java.util.logging.Level;
import java.util.logging.Logger;

final class ChronicleStore {
 static final int SCHEMA_VERSION=8;
 static final class Event {
  long ts; String profileId,sessionId,type,title,detail,source,category,expeditionId; long amount,value,haValue; int itemId,quantity,npcId,kc; boolean boss;
  Event(long ts,String profileId,String sessionId,String type,String title,String detail,long amount){this(ts,profileId,sessionId,type,title,detail,amount,"",0,0,0);}
  Event(long ts,String profileId,String sessionId,String type,String title,String detail,long amount,String source,long value,int itemId,int quantity){this.ts=ts;this.profileId=profileId;this.sessionId=sessionId;this.type=type;this.title=title;this.detail=detail;this.amount=amount;this.source=source;this.value=value;this.itemId=itemId;this.quantity=quantity;}
 }
 private static final Logger LOG=Logger.getLogger(ChronicleStore.class.getName());
 private final ScheduledExecutorService writer=Executors.newSingleThreadScheduledExecutor(r->{Thread t=new Thread(r,"RuneChronicle-persistence");t.setDaemon(true);return t;});
 private ScheduledFuture<?> pending;
 private long revision;
 private boolean dirty,closed;
 private final Gson gson;
 ChronicleStore(Gson gson,Filepath dir){this.gson=gson.newBuilder().setPrettyPrinting().create();this.dir=dir;this.file=dir.joinSegment("events.json");this.versionFile=dir.joinSegment("schema-version.txt");}
 private final Filepath dir,file,versionFile;
 private final List<Event> events=new ArrayList<>();
 synchronized void load(){try{dir.createDirectories();if(file.exists()){try(Reader r=file.openBufferedReader()){Event[] x=gson.fromJson(r,Event[].class);if(x!=null)events.addAll(Arrays.asList(x));}}versionFile.write(Integer.toString(SCHEMA_VERSION));}catch(Exception ignored){}}
 synchronized void add(Event e){if(closed)throw new IllegalStateException("Chronicle store is closed");events.add(e);markDirty();}
 synchronized void removeExpedition(String expeditionId){if(expeditionId==null||expeditionId.isEmpty())return;if(events.removeIf(e->expeditionId.equals(e.expeditionId)))markDirty();}
 synchronized List<Event> allFor(String p){List<Event>o=new ArrayList<>();for(Event e:events)if(p.equals(e.profileId))o.add(e);o.sort(Comparator.comparingLong(a->a.ts));return o;}
 synchronized List<Event> session(String p,String s){List<Event>o=new ArrayList<>();for(Event e:events)if(p.equals(e.profileId)&&s!=null&&s.equals(e.sessionId))o.add(e);o.sort(Comparator.comparingLong(a->a.ts));return o;}
 private void markDirty(){revision++;dirty=true;scheduleSave();}
 // Called under the state lock. Keep one pending write so sustained activity cannot starve persistence.
 private void scheduleSave(){if(!closed&&(pending==null||pending.isDone()))pending=writer.schedule(this::backgroundSave,1000,TimeUnit.MILLISECONDS);}
 private void backgroundSave(){
  synchronized(this){pending=null;}
  try{writeSnapshot();}catch(Exception ex){LOG.log(Level.WARNING,"Unable to persist Chronicle events",ex);}
  finally{synchronized(this){if(dirty)scheduleSave();}}
 }
 // Every disk operation runs on the same writer; the state lock covers only snapshot/revision work.
 private void writeSnapshot() throws IOException {
  List<Event> snapshot;long captured;
  synchronized(this){if(!dirty&&file.exists())return;snapshot=new ArrayList<>(events);captured=revision;}
  dir.createDirectories();Filepath temporary=dir.joinSegment("events.json.tmp");
  try(Writer w=temporary.openBufferedWriter()){gson.toJson(snapshot,w);}
  temporary.moveTo(file,java.nio.file.StandardCopyOption.REPLACE_EXISTING);
  synchronized(this){if(revision==captured)dirty=false;}
 }
 private <T> T awaitWrite(Callable<T> action) throws IOException {
  try{return CompletableFuture.supplyAsync(()->{try{return action.call();}catch(Exception ex){throw new CompletionException(ex);}},writer).join();}
  catch(CompletionException ex){throw new IOException("Chronicle persistence failed",ex.getCause());}
  catch(RejectedExecutionException ex){throw new IOException("Chronicle store is closed",ex);}
 }
 void save(){try{awaitWrite(()->{writeSnapshot();return null;});}catch(IOException ex){LOG.log(Level.WARNING,"Unable to persist Chronicle events",ex);}}
 Filepath exportBackup(Filepath destination) throws IOException {
  return awaitWrite(()->{writeSnapshot();file.copyTo(destination,java.nio.file.StandardCopyOption.REPLACE_EXISTING);return destination;});
 }
 int importBackup(Filepath source) throws IOException {
  Event[] imported;
  try(Reader r=source.openBufferedReader()){imported=gson.fromJson(r,Event[].class);if(imported==null)throw new IOException("Backup contains no Chronicle events");}
  catch(JsonParseException ex){throw new IOException("That file is not a valid RuneChronicle backup",ex);}
  synchronized(this){if(closed)throw new IOException("Chronicle store is closed");events.clear();events.addAll(Arrays.asList(imported));markDirty();}
  awaitWrite(()->{writeSnapshot();return null;});return imported.length;
 }
 void reset(){synchronized(this){if(closed)throw new IllegalStateException("Chronicle store is closed");events.clear();markDirty();}save();}
 void close(){
  synchronized(this){if(closed)return;closed=true;if(pending!=null)pending.cancel(false);}
  try{awaitWrite(()->{writeSnapshot();return null;});}
  catch(IOException ex){LOG.log(Level.WARNING,"Unable to flush Chronicle events on shutdown",ex);}
  finally{writer.shutdown();}
 }
 Filepath dataFile(){return file;}
 static long now(){return Instant.now().getEpochSecond();}
}

