 DropHistoryDialog(RuneChroniclePlugin p,ItemManager i){plugin=p;items=i;setTitle("RuneChronicle — Drop History");setModal(false);setSize(650,570);setLocationRelativeTo(null);setDefaultCloseOperation(DISPOSE_ON_CLOSE);JPanel root=new JPanel(new BorderLayout(10,10));root.setBorder(BorderFactory.createEmptyBorder(14,14,14,14));JPanel top=new JPanel(new BorderLayout(8,8));top.add(new JLabel("Search any Old School RuneScape item"),BorderLayout.NORTH);search.setToolTipText("Type part of an item name, e.g. fir for Fire cape");top.add(search);root.add(top,BorderLayout.NORTH);list.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);list.setPreferredSize(new Dimension(220,400));root.add(new JScrollPane(list),BorderLayout.WEST);results.setLayout(new BoxLayout(results,BoxLayout.Y_AXIS));root.add(new JScrollPane(results));setContentPane(root);search.getDocument().addDocumentListener(new DocumentListener(){public void insertUpdate(DocumentEvent e){filter();}public void removeUpdate(DocumentEvent e){filter();}public void changedUpdate(DocumentEvent e){filter();}});list.addListSelectionListener(e->{if(!e.getValueIsAdjusting())render(list.getSelectedValue());});emptyPrompt();}
