 private static JLabel label(String s,int z,Color c,int style){JLabel l=new JLabel(s);l.setForeground(c);l.setFont(ui(style,z));return l;}private static JLabel wrapLabel(String s,int z,Color c,int style,int width){String safe=s==null?"":s.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;");JLabel l=new JLabel("<html><body style='width:"+width+"px'>"+safe+"</body></html>");l.setForeground(c);l.setFont(ui(style,z));return l;}private static Font ui(int style,int z){return new Font("SansSerif",style,z);}private static String compact(long n){if(n>=1000000)return String.format(Locale.US,"%.2fM",n/1000000d);if(n>=1000)return String.format(Locale.US,"%.1fK",n/1000d);return String.format(Locale.US,"%,d",n);}private static String trim(String s,int n){return s.length()>n?s.substring(0,n-1)+"…":s;}private static Color color(String t){if("LOOT".equals(t))return GOLD;if("BOSS_KILL".equals(t))return GOLD;if("KILL".equals(t)||"DEATH".equals(t))return RED;if("LEVEL".equals(t))return GREEN;if("QUEST".equals(t)||"ACHIEVEMENT".equals(t))return PURPLE;if("PET".equals(t))return new Color(244,132,190);if("COLLECTION".equals(t))return CYAN;if("ACTIVITY".equals(t)||"CLUE".equals(t))return BLUE;return BLUE;}private static String symbol(String t){if("BOSS_KILL".equals(t))return"♛";if("KILL".equals(t))return"⚔";if("LEVEL".equals(t))return"↑";if("QUEST".equals(t))return"★";if("COLLECTION".equals(t))return"▣";if("PET".equals(t))return"♥";if("ACTIVITY".equals(t))return"◆";if("DEATH".equals(t))return"☠";return"•";}private static String kicker(ChronicleStore.Event e){if("BOSS_KILL".equals(e.type))return"BOSS DEFEATED";if("LOOT".equals(e.type))return e.category==null?"LOOT CLAIMED":e.category.toUpperCase(Locale.ROOT);if("PET".equals(e.type))return"RARE MOMENT";if("COLLECTION".equals(e.type))return"COLLECTION LOG";if("ACTIVITY".equals(e.type))return"ACTIVITY COMPLETE";if("PB".equals(e.type))return"PERSONAL BEST";return e.category==null?"":e.category.toUpperCase(Locale.ROOT);}
}

