 private void recordSupplyUse(int id,int q){if(q<=0)return;ItemComposition c=itemManager.getItemComposition(id);String name=c==null?("Item "+id):c.getName();long ge=Math.max(0L,itemManager.getItemPrice(id));java.util.regex.Matcher dose=java.util.regex.Pattern.compile(".*\\(([1-4])\\)$").matcher(name);if(dose.matches()){int d=Integer.parseInt(dose.group(1));if(d>0)ge=Math.max(1L,ge/d);}long value=(long)ge*q;ChronicleStore.Event ev=new ChronicleStore.Event(ChronicleStore.now(),profile,sessionId,"SUPPLY",name,"Used ×"+q+" · "+gp(ge)+" gp ea · "+gp(value)+" total",value,"Supplies",value,id,q);ev.category="Supplies Used";ev.expeditionId=expeditionActive?expeditionId:null;store.add(ev);if(expeditionActive)expeditionUsed.merge(id,(long)q,Long::sum);refresh();}
 private void recordRecoveredSupply(int id,int gained){if(!expeditionActive||gained<=0||!isAmmo(id))return;long used=expeditionUsed.getOrDefault(id,0L),already=expeditionRecovered.getOrDefault(id,0L),room=Math.max(0L,used-already);int q=(int)Math.min((long)gained,room);if(q<=0)return;ItemComposition c=itemManager.getItemComposition(id);String name=c==null?("Item "+id):c.getName();long ge=Math.max(0L,itemManager.getItemPrice(id)),value=ge*q;ChronicleStore.Event ev=new ChronicleStore.Event(ChronicleStore.now(),profile,sessionId,"RECOVERED_SUPPLY",name,"Recovered ×"+q+" · "+gp(ge)+" gp ea · "+gp(value)+" recovered",value,"Recovered Supplies",value,id,q);ev.category="Recovered Supplies";ev.expeditionId=expeditionId;store.add(ev);expeditionRecovered.merge(id,(long)q,Long::sum);refresh();}
