 ExpeditionSnapshot expeditionSnapshot(){if(!expeditionActive)return new ExpeditionSnapshot(false,0,0,0,0,0,new LinkedHashMap<>());long loot=0,supplies=0,recovered=0,kills=0;for(ChronicleStore.Event e:store.allFor(profile)){if(!Objects.equals(expeditionId,e.expeditionId))continue;if("LOOT".equals(e.type))loot+=e.value;else if("SUPPLY".equals(e.type))supplies+=e.value;else if("RECOVERED_SUPPLY".equals(e.type))recovered+=e.value;else if("KILL".equals(e.type)||"BOSS_KILL".equals(e.type))kills+=e.amount;}return new ExpeditionSnapshot(true,Math.max(0,ChronicleStore.now()-expeditionStart),loot,supplies,recovered,kills,new LinkedHashMap<>(expeditionUsed));}
