 void showDialog(){Window owner=null;dialog=new JDialog(owner,"RuneChronicle — Recap",Dialog.ModalityType.APPLICATION_MODAL);dialog.setDefaultCloseOperation(WindowConstants.DISPOSE_ON_CLOSE);dialog.addWindowListener(new java.awt.event.WindowAdapter(){@Override public void windowClosed(java.awt.event.WindowEvent e){cont.run();}});dialog.getRootPane().registerKeyboardAction(e->dialog.dispose(),KeyStroke.getKeyStroke("ESCAPE"),JComponent.WHEN_IN_FOCUSED_WINDOW);capture=buildShell();JScrollPane sc=new JScrollPane(capture);sc.setBorder(null);sc.getViewport().setBackground(BG);sc.getVerticalScrollBar().setUnitIncrement(20);dialog.setContentPane(sc);dialog.setSize(780,680);dialog.setMinimumSize(new Dimension(660,540));dialog.setLocationRelativeTo(owner);selectRange("SESSION");dialog.setVisible(true);}
 private JPanel buildShell(){JPanel root=new JPanel();root.setLayout(new BoxLayout(root,BoxLayout.Y_AXIS));root.setBackground(BG);root.setBorder(new EmptyBorder(16,26,20,26));
  JPanel brand=new JPanel(new FlowLayout(FlowLayout.CENTER,0,0));brand.setOpaque(false);brand.add(t("RUNE",11,WHITE,Font.BOLD));brand.add(t("CHRONICLE",11,GOLD,Font.BOLD));root.add(brand);
