 private JPanel bossTile(String n,long c){JPanel p=new JPanel(new BorderLayout(8,0));p.setBackground(SURFACE);p.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createLineBorder(LINE),new EmptyBorder(9,10,9,10)));JLabel a=new JLabel("♛",SwingConstants.CENTER);a.setForeground(GOLD);a.setFont(ui(Font.BOLD,18));a.setPreferredSize(new Dimension(36,36));portraits.apply(n,a,36);p.add(a,BorderLayout.WEST);JPanel x=new JPanel();x.setOpaque(false);x.setLayout(new BoxLayout(x,BoxLayout.Y_AXIS));x.add(t(n,10,WHITE,Font.BOLD));x.add(t("×"+c,10,GOLD,Font.BOLD));p.add(x);return p;}
